#include "../../models/film_three_finger_resume/FaceBranch.h"
#include "../../models/film_rail_tendon/ControlProfile.h"
#include <fstream>
#include <iostream>
#include <iomanip>
using namespace regrip_three_resume;
int main(int argc,char**argv){try{
 if(argc!=3&&argc!=4)throw std::runtime_error("checkpoint,prefix required");std::ifstream in(argv[1]);std::string magic,token;double time,h;unsigned step;in>>magic>>time>>h>>step>>token;SharedFilmSystem s(Layout(),{0,0,-.001},true,true);s.exactUnresolved=true;unsigned n=s.initial.size(),nf=s.shared.nf;Eigen::VectorXd q(n),v(n);for(double&x:q)in>>x;for(double&x:v)in>>x;double unused;for(unsigned i=0;i<4;++i)in>>unused;s.shared.M.setZero();for(unsigned f=0;f<3;++f){auto&m=s.shared.films[f].film;for(unsigned i=0;i<m.mass.size();++i){double mass;in>>mass;m.mass[i]=mass;for(unsigned d=0;d<3;++d){unsigned a=3*i+d;if(m.index[a]>=0)s.shared.M(f*nf+m.index[a],f*nf+m.index[a])+=mass*m.weight[a]*m.weight[a];}}}for(unsigned i=0;i<6;++i)for(unsigned j=0;j<6;++j)in>>s.shared.M(3*nf+i,3*nf+j);if(!in)throw std::runtime_error("checkpoint incomplete");std::vector<ContactOwner>owners;for(unsigned f=0;f<3;++f){auto row=s.selected(q,f);if(row.feature!=6)throw std::runtime_error("face event initial feature differs");owners.push_back({f,row.triangle,6});}
 auto branch=[&](const auto&x){return faceBranchGeometry(s,x,owners);};auto advance=[&](double interval){return regrip_collocation::persistentRows(s.shared.M,2,q,v,time,interval,[&](const auto&x,double t){return s.force(x,regrip_film_rail::ControlProfile::evaluate(t,.0001,.01,.02,.03,true).tension);},branch);};
 struct Inactive{double gap;unsigned finger,triangle,feature;double aliasGap=1e100;unsigned aliases=0;};auto inactive=[&](const Eigen::VectorXd&x){Inactive out{1e100,0,0,0};for(unsigned f=0;f<3;++f){auto state=s.local(x,f);const auto&sys=s.shared.films[f];for(unsigned k=0;k<sys.triangles.size();++k)if(k!=owners[f].triangle){auto e=sys.primitive(state,k);bool alias=argc==4;std::vector<unsigned>support;if(e.feature<3)support={sys.triangles[k][e.feature]};else if(e.feature==3)support={sys.triangles[k][0],sys.triangles[k][1]};else if(e.feature==4)support={sys.triangles[k][0],sys.triangles[k][2]};else if(e.feature==5)support={sys.triangles[k][1],sys.triangles[k][2]};else support={sys.triangles[k][0],sys.triangles[k][1],sys.triangles[k][2]};for(unsigned node:support)if(std::find(sys.triangles[owners[f].triangle].begin(),sys.triangles[owners[f].triangle].end(),node)==sys.triangles[owners[f].triangle].end())alias=false;if(alias){out.aliasGap=std::min(out.aliasGap,e.gap.v);++out.aliases;continue;}if(e.gap.v<out.gap){out.gap=e.gap.v;out.finger=f;out.triangle=k;out.feature=e.feature;}}}return out;};auto initial=inactive(q);if(initial.gap<=0||minimumFaceParameter(s,q,owners)<=0)throw std::runtime_error("strict initial face/inactive branch not separated");auto whole=advance(h);auto predicted=inactive(whole.q);double predictedBary=minimumFaceParameter(s,whole.q,owners);if(predicted.gap>0&&predictedBary>0)throw std::runtime_error("no signed endpoint branch event");double lo=0,hi=h;unsigned evaluations=1;
 for(unsigned i=0;i<48&&hi-lo>1e-13;++i){double mid=(lo+hi)/2;auto result=advance(mid);++evaluations;auto other=inactive(result.q);if(other.gap>0&&minimumFaceParameter(s,result.q,owners)>0)lo=mid;else hi=mid;}
 double eventH=(lo+hi)/2;auto event=advance(eventH);++evaluations;auto other=inactive(event.q);double bary=minimumFaceParameter(s,event.q,owners),gap=s.clearance(event.q);for(const auto&stage:event.stages)gap=std::min(gap,s.clearance(stage.q));if(gap< -1e-10)throw std::runtime_error("pre-event whole-stage gap fails");std::string prefix=argv[2];std::ofstream metrics(prefix+".metrics.csv");metrics<<std::setprecision(17)<<"event_time_s,bracket_width_s,minimum_face_parameter,minimum_inactive_gap_mm,inactive_finger,inactive_triangle,inactive_feature,minimum_pre_stage_gap_mm,momentum_Ns,normal_velocity_mm_s,evaluations\n"<<time+eventH<<','<<hi-lo<<','<<bary<<','<<other.gap<<','<<other.finger<<','<<other.triangle<<','<<other.feature<<','<<gap<<','<<event.momentumResidual<<','<<event.velocityResidual<<','<<evaluations<<'\n';std::ofstream params(prefix+".parameters.csv");params<<std::setprecision(17)<<"finger,triangle,a,b,c,normal_force_N\n";for(unsigned f=0;f<3;++f){auto value=faceBranch(relativeTriangle(s,event.q,owners[f]),s.layout.bufferRadius);params<<f<<','<<owners[f].triangle;for(double x:value.barycentric)params<<','<<x;params<<','<<event.stages[1].force(f)<<'\n';}std::ofstream states(prefix+".states.txt");states<<std::setprecision(17)<<"EVENT "<<time+eventH<<'\n'<<event.q.transpose()<<'\n'<<event.v.transpose()<<'\n';std::cout<<"PASS independent first identified face-boundary/inactive-distance predicate root;NOT global earliest CCD/SOFA/post-event continuation\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
